import express, { NextFunction, Request, Response } from "express";
import { CreateTaskInput, TaskService } from "../application/task-service";
import { ConflictError, NotFoundError, ValidationError } from "../domain/errors";
import { Task, TaskStatus } from "../domain/entities";
import {
  InMemoryProjectRepository,
  InMemoryTaskRepository,
  InMemoryUserRepository,
} from "./in-memory-repositories";

type ObjectBody = Record<string, unknown>;

export function createApp(service = createTaskService()): express.Express {
  const app = express();
  app.use(express.json());

  app.post("/users", (req, res, next) => {
    try { res.status(201).json(service.createUser(readText(req.body, "name"))); } catch (error) { next(error); }
  });
  app.post("/projects", (req, res, next) => {
    try { res.status(201).json(service.createProject(readText(req.body, "name"))); } catch (error) { next(error); }
  });
  app.post("/projects/:projectId/tasks", (req, res, next) => {
    try { res.status(201).json(toTaskResponse(service.createTask(readParam(req, "projectId"), readTaskInput(req.body)))); } catch (error) { next(error); }
  });
  app.get("/projects/:projectId/tasks", (req, res, next) => {
    try {
      const status = readQuery(req, "status");
      const assigneeId = readQuery(req, "assigneeId") ?? readQuery(req, "assignee");
      const filter = { ...(status === undefined ? {} : { status: status as TaskStatus }), ...(assigneeId === undefined ? {} : { assigneeId }) };
      res.json(service.listTasks(req.params.projectId, filter).map(toTaskResponse));
    } catch (error) { next(error); }
  });
  const complete = (req: Request, res: Response, next: NextFunction): void => {
    try {
      const projectId = typeof req.params.projectId === "string" ? req.params.projectId : undefined;
      res.json(toTaskResponse(service.markDone(readParam(req, "taskId"), projectId)));
    } catch (error) { next(error); }
  };
  app.patch("/tasks/:taskId/done", complete);
  app.patch("/projects/:projectId/tasks/:taskId/done", complete);

  app.use((error: unknown, _req: Request, res: Response, _next: NextFunction) => {
    if (error instanceof ValidationError) return void res.status(400).json({ error: error.message });
    if (error instanceof NotFoundError) return void res.status(404).json({ error: error.message });
    if (error instanceof ConflictError) return void res.status(409).json({ error: error.message });
    if (error instanceof SyntaxError && "body" in error) return void res.status(400).json({ error: "invalid JSON" });
    res.status(500).json({ error: "internal server error" });
  });
  return app;
}

export function createTaskService(): TaskService {
  return new TaskService(new InMemoryUserRepository(), new InMemoryProjectRepository(), new InMemoryTaskRepository());
}

function readTaskInput(value: unknown): CreateTaskInput {
  const body = asObject(value);
  return {
    title: readText(body, "title"),
    description: readText(body, "description"),
    ...(body.dueDate === undefined ? {} : { dueDate: readText(body, "dueDate") }),
    ...(body.status === undefined ? {} : { status: readText(body, "status") as TaskStatus }),
    ...(body.assigneeId === undefined ? {} : { assigneeId: readText(body, "assigneeId") }),
  };
}

function readText(value: unknown, property: string): string {
  const candidate = asObject(value)[property];
  if (typeof candidate !== "string") throw new ValidationError(`${property} is required`);
  return candidate;
}

function asObject(value: unknown): ObjectBody {
  if (value === null || typeof value !== "object" || Array.isArray(value)) throw new ValidationError("request body must be an object");
  return value as ObjectBody;
}

function readQuery(request: Request, name: string): string | undefined {
  const value = request.query[name];
  if (value === undefined) return undefined;
  if (typeof value !== "string") throw new ValidationError(`${name} must be a string`);
  return value;
}

function readParam(request: Request, name: string): string {
  const value = request.params[name];
  if (typeof value !== "string") throw new ValidationError(`${name} is required`);
  return value;
}

function toTaskResponse(task: Task): Omit<Task, "dueDate"> & { dueDate?: string } {
  const { dueDate, ...taskWithoutDate } = task;
  return { ...taskWithoutDate, ...(dueDate === undefined ? {} : { dueDate: dueDate.toISOString() }) };
}

